using System.Text.Json;
using VisionFramework;
using VisionPluginContracts;
using VisionIO;
namespace VisionPlugins.ImageSource;
public sealed class ImageSourcePlugin:IVisionToolPlugin,IToolImageListProvider,IWpfToolEditorFactory {
 public ToolManifest Manifest{get;}=new("vision.image-source","1.0.0","图像源","collection","tool-image-file.png");
 static JsonElement J<T>(T value)=>JsonSerializer.SerializeToElement(value);
 static ParameterDescriptor P<T>(string name,ParameterKind kind,T value,double? min=null,double? max=null)=>new(name,kind,true,J(value),min,max);
 public ModuleDescriptor Descriptor{get;}=new("vision.image-source","1.0.0","图像源",[],[new("Image",DataKind.GrayImage),new("Width",DataKind.Integer),new("Height",DataKind.Integer),new("PixelFormat",DataKind.Integer),new("SNCode",DataKind.Integer),new("CurImageName",DataKind.Text),new("CurImagePath",DataKind.Text),new("ModuStatus",DataKind.Integer),new("ModuRunTime",DataKind.Number),new("ImageMono8",DataKind.GrayImage,false),new("WidthMono8",DataKind.Integer,false),new("HeightMono8",DataKind.Integer,false),new("PixelFormatMono8",DataKind.Integer,false)],[
 P("ImageSourceType",ParameterKind.Integer,1,1,3),P("PixelFormat",ParameterKind.Integer,1,1,2),P("SolSaveImageData",ParameterKind.Boolean,false),P("ShowImageName",ParameterKind.Boolean,true),P("InitialSN",ParameterKind.Integer,1,0,100000),P("PathCache",ParameterKind.Integer,0,0,5),P("StitchEnable",ParameterKind.Boolean,false),P("AutoPlay",ParameterKind.Boolean,true),P("AutoStop",ParameterKind.Boolean,false),P("TriggerStringEnable",ParameterKind.Boolean,false),P("IsSubscribeFolderMode",ParameterKind.Boolean,false),P("SubscribeFolderPath",ParameterKind.Text,""),P("RefreshImage",ParameterKind.Boolean,true),P("TriggerProcessRun",ParameterKind.Boolean,false),P("CameraID",ParameterKind.Integer,-1),P("CurrentImagePath",ParameterKind.Text,""),P("ImagePaths",ParameterKind.Text,"[]"),P("Interval",ParameterKind.Integer,0,0),P("ExecuteType",ParameterKind.Integer,1,1,2),P("SelectedPaths",ParameterKind.Text,"[]"),P("StitchStartHeight",ParameterKind.Integer,0,0),P("StitchHeight",ParameterKind.Integer,2000,1),P("ClearTrigger",ParameterKind.Boolean,false),P("OutMono8",ParameterKind.Boolean,false),P("SetCameraParamWaitTime",ParameterKind.Integer,0,0)]);
 readonly Dictionary<string,State> states=new();readonly object gate=new();sealed class State{public string Signature="";public int Index;public long Sequence;public bool End;}
 public IReadOnlyList<ToolImageEntry> GetImages(NodeDocument node){var paths=JsonSerializer.Deserialize<string[]>(node.Parameters["ImagePaths"].GetString()??"[]")??[];return paths.Select(p=>new ToolImageEntry(p,p==node.Parameters["CurrentImagePath"].GetString())).ToArray();}
 public IModule CreateRuntime()=>new Runtime(this);
 public Form CreateEditor(ToolEditorContext context)=>throw new InvalidOperationException("Use WPF editor factory");
 public System.Windows.Window CreateWpfEditor(ToolEditorContext context)=>new ImageSourceWindow(context);
 public void Reset(string nodeId){lock(gate)states.Remove(nodeId);}
 sealed class Runtime(ImageSourcePlugin owner):IModule {
 public ModuleDescriptor Descriptor=>owner.Descriptor;
 public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token){token.ThrowIfCancellationRequested();try{lock(owner.gate){if(c.Integer("ImageSourceType")!=1)return Done(ModuleStatus.Failed,"InputProviderUnavailable","该输入模式尚未接入独立提供器");if(c.Integer("PixelFormat")!=1)return Done(ModuleStatus.Failed,"PixelFormatUnavailable","RGB24 输出契约尚未接入");if(c.Integer("PathCache")!=0||c.Integer("Interval")!=0)return Done(ModuleStatus.Failed,"TimingOrCacheUnavailable","缓存和间隔调度尚未实现");if(c.Boolean("StitchEnable"))return Done(ModuleStatus.Failed,"StitchUnavailable","拼接尚未实现");if(c.Boolean("SolSaveImageData"))return Done(ModuleStatus.Failed,"ModelEmbeddingUnavailable","方案嵌入图像尚未实现");if(c.Boolean("TriggerStringEnable")||c.Boolean("ClearTrigger")||c.Boolean("TriggerProcessRun"))return Done(ModuleStatus.Failed,"TriggerUnavailable","触发服务尚未接入");string[] paths=JsonSerializer.Deserialize<string[]>(c.Text(c.Integer("ExecuteType")==2?"SelectedPaths":"ImagePaths"))??[];if(c.Boolean("IsSubscribeFolderMode")){string folder=c.ResolvePath(c.Text("SubscribeFolderPath"));paths=Directory.EnumerateFiles(folder,"*.bmp").OrderBy(p=>p,StringComparer.Ordinal).ToArray();}if(paths.Any(string.IsNullOrWhiteSpace))return Done(ModuleStatus.Failed,"InvalidImageList","图像列表包含空路径");if(paths.Length==0&&c.Integer("ExecuteType")==1&&!c.Boolean("IsSubscribeFolderMode")&&!string.IsNullOrWhiteSpace(c.Text("CurrentImagePath")))paths=[c.Text("CurrentImagePath")];if(paths.Length==0)return Done(ModuleStatus.Failed,"NoImage","未配置本地图像");string signature=JsonSerializer.Serialize(c.Parameters)+JsonSerializer.Serialize(paths);if(!owner.states.TryGetValue(c.NodeId,out var state)||state.Signature!=signature)owner.states[c.NodeId]=state=new(){Signature=signature,Sequence=c.Integer("InitialSN"),Index=Math.Max(0,Array.IndexOf(paths,c.Text("CurrentImagePath")))};if(state.End)return Done(ModuleStatus.NoMatch,"EndOfImages","最后一张图像已执行，已停止");int index=c.Boolean("AutoPlay")?state.Index:Math.Max(0,Array.IndexOf(paths,c.Text("CurrentImagePath")));var clock=System.Diagnostics.Stopwatch.StartNew();using var stream=File.OpenRead(c.ResolvePath(paths[index]));var image=BmpReader.Read(stream);token.ThrowIfCancellationRequested();var values=new Dictionary<string,PortValue>{{"Image",PortValue.Image(image)},{"Width",PortValue.Integer(image.Width)},{"Height",PortValue.Integer(image.Height)},{"SNCode",PortValue.Integer(state.Sequence++)},{"CurImageName",PortValue.Text(Path.GetFileName(paths[index]))},{"CurImagePath",PortValue.Text(c.ResolvePath(paths[index]))},{"PixelFormat",PortValue.Integer(0x1080001)},{"ModuStatus",PortValue.Integer(1)},{"ModuRunTime",PortValue.Number(clock.Elapsed.TotalMilliseconds)}};if(c.Boolean("OutMono8")){values["ImageMono8"]=PortValue.Image(image);values["WidthMono8"]=PortValue.Integer(image.Width);values["HeightMono8"]=PortValue.Integer(image.Height);values["PixelFormatMono8"]=PortValue.Integer(0x1080001);}if(c.Boolean("AutoPlay")){state.Index=(index+1)%paths.Length;state.End=c.Boolean("AutoStop")&&index==paths.Length-1;}return new(new ModuleResult(ModuleStatus.Success,values));}}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException or ArgumentException or InvalidOperationException){return Done(ModuleStatus.Failed,"ImageReadFailed",ex.Message);}}
 static ValueTask<ModuleResult> Done(ModuleStatus status,string code,string message)=>new(new ModuleResult(status,new Dictionary<string,PortValue>(),code,message));
 }
}
